"Subskrypcja zostanie od razu anulowana i nie pobierzemy kolejnej opłaty. Opłacony czas dostępu przepada razem z kontem, bez zwrotu pieniędzy.": "Your subscription will be cancelled right away and we won't charge you again. Paid access time is lost with the account, without a refund.",
