"Usuwanie konta nie jest jeszcze włączone. Nic nie zostało usunięte. Napisz do nas.": "Account deletion isn't switched on yet. Nothing was deleted. Write to us.",
"Dane są usunięte, ale konta nie udało się zamknąć. Napisz do nas, dokończymy.": "Your data is deleted, but the account couldn't be closed. Write to us and we'll finish it.",
