"Pytania, które nie wyszły w quizie, grze, lekcji albo próbnym teście, wracają na rewanż: zwykle następnego dnia, potem po kilku dniach i po około tygodniu, szybciej, jeśli dalej sprawiają kłopot. Rewanż liczy się innego dnia niż błąd. Trzy wygrane z rzędu i pytanie jest pokonane.": "Questions that went wrong in a quiz, game, lesson or practice test come back for a rematch: usually the next day, then after a few days and after about a week, sooner if they still give you trouble. A rematch counts on a different day than the mistake. Three wins in a row and the question is defeated.",
