"Ogłoszenia prowadzących o odwołanych zajęciach. Zatwierdzone odwołanie działa jak komunikat dziekanatu: zajęcia są przekreślone w Kalendarzu i na Dziś, Po zajęciach ich nie proponuje, a temat z sylabusa przechodzi na następne zajęcia. Plan na plan.skrotbm.pl i kalendarz w telefonie dostają to przy najbliższym sprawdzeniu planu (co godzinę w dzień).": "Lecturers' notices about cancelled classes. An approved cancellation works like a dean's office notice: the class is crossed out in Calendar and on Today, After class no longer suggests it, and the syllabus topic moves to the next class. plan.skrotbm.pl and the phone calendar get it at the next timetable check (hourly during the day).",
