"Pamięć – jeszcze raz": "Memory – once more",
"Kilka pytań i krótka gra pamięciowa, ok. 6 minut. Wynik lekko ustawi odstępy powtórek fiszek i pokaże Ci, co Ci pomaga.": "A few questions and a short memory game, about 6 minutes. The result gently sets your flashcard review gaps and shows you what helps you.",
