"Odpowiedz na oba pytania.": "Answer both questions.",
"Pokażemy Ci 6 słów z wymyślonego języka, każde przez 5 sekund. Potem sprawdzimy, ile pamiętasz – od razu i jeszcze raz na końcu.": "We'll show you 6 words from a made-up language, 5 seconds each. Then we'll check how many you remember – right away and once more at the end.",
