"Jak długo zwykle uczysz się w jednym ciągu, zanim zaczniesz zerkać w telefon?": "How long do you usually study in one go before you start checking your phone?",
"Wolisz jedną dłuższą sesję czy kilka krótkich w ciągu dnia?": "Do you prefer one longer session or several short ones a day?",
"Co najbardziej pomaga Ci zabrać się do nauki?": "What helps you most to get started?",
"Wybierz do {0}.": "Pick up to {0}.",
"Do {0}.": "Up to {0}.",
"Jak bardzo stresują Cię kolokwia i egzaminy?": "How stressed are you by tests and exams?",
"1 – wcale, 5 – bardzo. Sama liczba nie jest zapisywana.": "1 – not at all, 5 – very. The number itself isn't saved.",
"Wybierz, co Cię nakręca, i zaznacz stres.": "Pick what gets you going and mark your stress.",
"Czym się interesujesz?": "What are you into?",
"Ostatnia rzecz: pamiętasz jeszcze słowa z gry?": "Last thing: do you still remember the words from the game?",
"Twój profil na start": "Your starting profile",
"To punkt startu. Po kilku tygodniach nauki profil ułoży się według tego, co faktycznie robisz.": "This is a starting point. After a few weeks of studying, the profile follows what you actually do.",
"Profil nauki jeszcze nie działa w bazie. Spróbuj za kilka dni.": "The learning profile isn't switched on in the database yet. Try again in a few days.",
"Nie udało się zapisać. Sprawdź internet i spróbuj jeszcze raz.": "Couldn't save. Check your connection and try again.",
"z testu": "from the test",
"Najjaśniej myśli Ci się rano.": "Your mind is clearest in the morning.",
"Najjaśniej myśli Ci się po południu.": "Your mind is clearest in the afternoon.",
"Najjaśniej myśli Ci się wieczorem.": "Your mind is clearest in the evening.",
"Porę dnia sprawdzimy, kiedy zbierze się więcej nauki.": "We'll check the time of day once there's more study to go on.",
"Śpisz ok. {0}: powtórki najlepiej skończyć pół godziny wcześniej.": "You sleep at about {0}: best to finish reviews half an hour earlier.",
"Twoja odpowiedź z testu. Po kilku tygodniach nauki zobaczysz, o której naprawdę idzie Ci najlepiej.": "Your answer from the test. After a few weeks of studying you'll see when it really goes best.",
"Z {0} słówek po kilku minutach pamiętasz {1}.": "Of {0} words, you remember {1} after a few minutes.",
"Fiszki zaczynają w trochę rzadszym rytmie.": "Flashcards start a little less often.",
"Fiszki zaczynają w trochę częstszym rytmie.": "Flashcards start a little more often.",
"Fiszki zaczynają w standardowym rytmie.": "Flashcards start at the standard pace.",
"Potem wracają tak, jak je oceniasz.": "After that they come back as you rate them.",
"Termin każdej fiszki liczy algorytm FSRS z Twoich ocen: co pamiętasz, wraca rzadziej. Wynik gry pamięciowej przesuwa tylko pierwsze odstępy i znika po 10 powtórkach.": "The FSRS algorithm sets each card's date from your ratings: what you remember comes back less often. The memory game only shifts the first gaps and fades out after 10 reviews.",
"Uczysz się w jednym ciągu ok. {0} minut.": "You study in one go for about {0} minutes.",
"Długość skupienia sprawdzimy po kilku sesjach.": "We'll check your focus span after a few sessions.",
"Tyle mniej więcej trwa seria powtórek albo lekcja.": "That's roughly one review series or one lesson.",
"Twoja odpowiedź z testu. Krótka przerwa między seriami pomaga utrzymać uwagę.": "Your answer from the test. A short break between series helps you stay focused.",
"Nic nie wybrano.": "Nothing picked.",
"Pomaga Ci:": "What helps you:",
"Zainteresowania:": "Interests:",
"Twoja odpowiedź z testu. Zmienisz ją, robiąc test jeszcze raz.": "Your answer from the test. Change it by taking the test again.",
"Twoje dane": "Your data",
"Ucz się na moich danych": "Learn from my data",
"Profil dopasowuje się do tego, jak Ci idzie. Wyłączone: zostają tylko oceny fiszek i bilety wyjścia, potrzebne do powtórek.": "The profile adapts to how it's going. Off: only flashcard ratings and exit tickets stay, as reviews need them.",
"Zacznij profil od nowa": "Start the profile over",
"Usuń dane o aktywności": "Delete activity data",
"Usunąć dane o aktywności (sesje, przerwy, przebieg testu)? Tego nie da się cofnąć. Fiszki, lekcje i postęp zostają.": "Delete activity data (sessions, breaks, test progress)? This can't be undone. Flashcards, lessons and progress stay.",
"Wyłączone. Nie zbieramy już danych o sesjach i przerwach.": "Off. We no longer collect data about sessions and breaks.",
"Włączone.": "On.",
"Profil zaczyna od nowa. Fiszki i postęp zostały.": "The profile starts over. Flashcards and progress stay.",
"Dane o aktywności usunięte.": "Activity data deleted.",
"Nie udało się. Sprawdź internet i spróbuj jeszcze raz.": "That didn't work. Check your connection and try again.",
"rytm, pamięć, skupienie i Twoje dane": "rhythm, memory, focus and your data",
"6 minut: jak się uczysz": "6 minutes: how you learn",
"2–3 dni": "2–3 days",
"do tygodnia": "within a week",
"do 2 tygodni": "within 2 weeks",
"do miesiąca": "within a month",
"dalej": "later",
"wracają za… →": "come back in… →",
"Każde „Pamiętam” odsuwa fiszkę dalej i wraca ona coraz rzadziej. „Nie pamiętam” sprowadza ją z powrotem na jutro.": "Every \"I remember\" pushes a card further out, so it comes back less and less often. \"I don't remember\" brings it back for tomorrow.",
"Fiszki wracają same, zanim zdążysz je zapomnieć: najpierw po kilku dniach, potem coraz rzadziej. Termin liczy algorytm FSRS z Twoich ocen.": "Flashcards come back on their own before you forget them: first after a few days, then less and less often. The FSRS algorithm sets the date from your ratings.",
"Fiszki wracają same, zanim je zapomnisz: najpierw po kilku dniach, potem coraz rzadziej. Tu też są gry z pytaniami z przedmiotu i mapa tego, co już umiesz.": "Flashcards come back on their own before you forget them: first after a few days, then less and less often. Here you'll also find games with questions from the subject and a map of what you already know.",
"start": "start",
"najrzadziej": "least often",
"Z tego przedmiotu starczyło na ok. {0} min.": "This subject had enough for about {0} min.",
"Lekcja na przejazd": "Lesson for the ride",
"🚋 Lekcja na przejazd": "🚋 Lesson for the ride",
"🚋 Jedziesz na zajęcia?": "🚋 Heading to class?",
"Fiszki z „Dziś do powtórki” i krótkie mikrolekcje z tego przedmiotu, dokładnie na tyle minut, ile jedziesz. Przewijasz je kciukiem.": "Flashcards from “Due today” and short micro-lessons from this subject, exactly as many minutes as your ride. Scroll through them with your thumb.",
"Ułóż mi przejazd →": "Plan my ride →",
"Układam playlistę…": "Building your playlist…",
"Zbieram fiszki i mikrolekcje.": "Collecting flashcards and micro-lessons.",
"Ile jedziesz?": "How long is your ride?",
"Dojedziesz na zajęcia z jednym tematem w głowie. Wybierz, ile trwa dojazd, a ułożymy fiszki i mikrolekcje dokładnie na ten czas.": "Arrive at class with one topic in your head. Pick how long your commute takes and we will line up flashcards and micro-lessons for exactly that time.",
