"Nie ma jeszcze nic do ułożenia z tego przedmiotu (brak lekcji i fiszek, które możesz otworzyć). Wybierz inny przedmiot.": "There is nothing to line up from this subject yet (no lessons or flashcards you can open). Pick another subject.",
