"10 minut przed snem": "10 minutes before sleep",
"🌙 10 minut przed snem": "🌙 10 minutes before sleep",
"tylko dzisiejsze błędy, bez nowego materiału": "only today’s mistakes, no new material",
"Powtórz dzisiejsze błędy": "Go over today’s mistakes",
"Bez nowego materiału. Powtórka tuż przed snem pomaga mózgowi utrwalić to, co było dziś do nauki.": "No new material. Reviewing right before sleep helps your brain lock in what you studied today.",
"Zaczynamy 🌙": "Let’s start 🌙",
"Zbieram dzisiejsze błędy…": "Collecting today’s mistakes…",
"Dziś bez błędów do powtórki": "No mistakes to review today",
"Nie było dziś „Nie pamiętam” ani złych odpowiedzi. Śpij spokojnie 😴": "No “I don’t remember” and no wrong answers today. Sleep well 😴",
"Dobranoc": "Good night",
"Tylko dzisiejsze błędy": "Only today’s mistakes",
"{0} {1} do powtórki, około {2} min. Nic nowego.": "{0} {1} to review, about {2} min. Nothing new.",
"Powtórka tuż przed snem pomaga mózgowi utrwalić to, co było dziś do nauki. Potem odłóż telefon.": "Reviewing right before sleep helps your brain lock in what you studied today. Then put the phone away.",
"Dobranoc, mózg pracuje dalej 😴": "Good night, your brain keeps working 😴",
"Powtórzone: {0}. Od razu dobrze: {1}.": "Reviewed: {0}. Right first time: {1}.",
"Fiszka · {0}": "Flashcard · {0}",
"Pamiętam ✓": "I remember ✓",
"Pytanie · {0}": "Question · {0}",
"Dobrze. ": "Correct. ",
"Tym razem nie.": "Not this time.",
"Tym razem nie. ": "Not this time. ",
"Lekcja na przejazd i przed snem": "Ride lesson and before sleep",
"Jadę 20 minut tramwajem. Da się wtedy coś zrobić?": "I ride the tram for 20 minutes. Can I do something then?",
"Tak: Więcej → Lekcja na przejazd. Wybierasz, ile jedziesz, a strona układa fiszki z „Dziś do powtórki” i krótkie mikrolekcje z jednego przedmiotu (najbliższe zajęcia) dokładnie na ten czas. Przewijasz je kciukiem. Do dwóch godzin przed zajęciami karta pojawia się też sama na ekranie Dziś.": "Yes: More → Lesson for the ride. You pick how long the ride is, and the site lines up flashcards from “Due today” and short micro-lessons from one subject (your next class) for exactly that time. You scroll through them with your thumb. Up to two hours before class the card also shows up on the Today screen by itself.",
"Co to jest „10 minut przed snem”?": "What is “10 minutes before sleep”?",
"Po 21:30 na ekranie Dziś pojawia się karta z dzisiejszymi błędami: fiszkami, przy których było „Nie pamiętam”, i złymi odpowiedziami z quizów i gier. Bez nowego materiału, w ciemnym, ciepłym wyglądzie i większymi literami. O każdej porze znajdziesz to w Więcej → 10 minut przed snem.": "After 9:30 pm the Today screen shows a card with today’s mistakes: flashcards where you chose “I don’t remember” and wrong answers from quizzes and games. No new material, in a dark, warm look with bigger letters. Any time of day you will find it in More → 10 minutes before sleep.",
"Pseudonim i widoczność": "Nickname and visibility",
"Pseudonim: {0} · widoczny": "Nickname: {0} · visible",
"Pseudonim: {0} · ukryty": "Nickname: {0} · hidden",
"Program studiów z semestrami 1–6 (z porównaniem przedmiotów do wyboru), szkolenia obowiązkowe, wygląd strony i Twoje konto. Słowniczek, lektury i zasady zaliczeń są w Przedmiotach, a język zmieniasz przyciskiem EN w nagłówku.": "The study programme for semesters 1–6 (with a comparison of electives), mandatory trainings, site looks and your account. The glossary, reading lists and grading rules are in Subjects, and you change the language with the EN button in the header.",
"Na górze Więcej jest Twój profil: poziom, XP i seria dni (kliknij, żeby zobaczyć nagrody i odznaki z gier). Do tego przewodnika wrócisz przez Więcej → Pomoc.": "At the top of More is your profile: level, XP and day streak (tap it to see rewards and game badges). You can come back to this guide via More → Help.",
"Nie. W rankingu widać tylko pseudonim i punkty. Możesz się też całkiem ukryć: Więcej → Ranking kierunku → Pseudonim i widoczność.": "No. The ranking only shows your nickname and points. You can also hide completely: More → Programme ranking → Nickname and visibility.",
"Dziś: +{0} XP": "Today: +{0} XP",
"Dziś: +{0} XP. Możesz teraz zrobić przerwę, wszystko jest zapisane.": "Today: +{0} XP. You can take a break now, everything is saved.",
"XP: punkty za naukę": "XP: points for studying",
