"#{0} w tym tygodniu · {1} pkt": "#{0} this week · {1} pts",
"Gry, Hasło dnia, ranking i Twoje pliki. Słowniczek, lektury i zasady zaliczeń są w Przedmiotach.": "Games, Word of the day, ranking and your files. The glossary, reading lists and grading rules are in Subjects.",
"Twoje pliki, ranking kierunku, sklep z monetami, program studiów i konto.": "Your files, the programme ranking, the coin shop, the study programme and your account.",
"jedne zajęcia": "one class",
"{0} masz jedne zajęcia": "{0} you have one class",
"Odwołane: jedne zajęcia (przekreślone niżej).": "Cancelled: one class (crossed out below).",
"Najbliższe 2 tygodnie": "Next 2 weeks",
"Test": "Test",
"Zaliczenia z sylabusów, których daty prowadzący jeszcze nie ogłosili:": "Exams from the syllabi whose dates the lecturers haven't announced yet:",
"👀 Zobacz przykładową lekcję bez logowania": "👀 See a sample lesson without logging in",
"Czym to się różni od slajdów z Teams?": "How is this different from the Teams slides?",
"Slajdy służą nam tylko za listę tematów. Lekcje, przykłady, fiszki i quizy piszemy od nowa, prostym językiem, z wersją po polsku.": "We use the slides only as a list of topics. Lessons, examples, flashcards and quizzes are written from scratch in plain language, with a Polish version.",
"Czy po 3 dniach coś zapłacę automatycznie?": "Will I be charged automatically after 3 days?",
"Nie. Okres próbny nie wymaga karty. Po 3 dniach dostęp się kończy, chyba że sam wybierzesz plan.": "No. The trial needs no card. After 3 days access ends unless you choose a plan yourself.",
"Ile to kosztuje?": "How much does it cost?",
"199 zł jednorazowo za oba semestry (do 11 lipca 2027) albo 35 zł miesięcznie.": "199 zł one-off for both semesters (until 11 July 2027) or 35 zł a month.",
"Zacznij {0} dni za darmo": "Start {0} days free",
"Zacznij 3 dni za darmo": "Start 3 days free",
"Przykładowa lekcja · Ochrona własności intelektualnej": "Sample lesson · Intellectual Property Protection",
"Przykładowa lekcja": "Sample lesson",
"Podstawowe zasady prawa własności intelektualnej": "Basic principles of intellectual property law",
"Tak wygląda wersja „Prościej · PL”. Każda lekcja ma też pełną wersję po angielsku, fiszki, quiz i bilet wyjścia.": "This is the “Simpler · PL” version. Every lesson also has a full English version, flashcards, a quiz and an exit ticket.",
"Ładuję przykładową lekcję…": "Loading the sample lesson…",
"Nie udało się wczytać przykładu. Spróbuj za chwilę.": "Couldn't load the sample. Try again in a moment.",
"Data szacowana": "Estimated date",
"data szacowana": "estimated date",
"Data szacowana: prowadzący jej jeszcze nie ogłosił. Pokazujemy ostatnie zajęcia z planu albo okres sesji. Sprawdź u prowadzącego.": "Estimated date: the lecturer hasn't announced it yet. We show the last class from the timetable or the exam period. Check with the lecturer.",
"prowadzący jeszcze nie podał daty": "the lecturer hasn't given a date yet",
"Wcześniej, ale data szacowana:": "Earlier, but the date is estimated:",
"Szacowane terminy": "Estimated dates",
"Tych dat prowadzący jeszcze nie ogłosili. Pokazujemy ostatnie zajęcia z planu albo okres sesji, żeby było wiadomo, kiedy mniej więcej się uczyć. Gdy data zostanie ogłoszona, termin przejdzie wyżej.": "The lecturers haven't announced these dates yet. We show the last class from the timetable or the exam period, so you roughly know when to study. Once a date is announced, it moves up.",
"Minione": "Past",
"Kolokwia i egzaminy, które już były, oraz terminy sprzed Twojego dołączenia. Nie liczą się do „po terminie”.": "Tests and exams that have already happened, and deadlines from before you joined. They don't count as overdue.",
"Żółty znaczek „Data szacowana” oznacza, że prowadzący jeszcze nie podał daty. Takie terminy są w osobnej sekcji „Szacowane terminy”.": "The yellow “Estimated date” badge means the lecturer hasn't given a date yet. Such dates are in a separate “Estimated dates” section.",
"Odhaczasz tylko zadania do oddania. Kolokwium i egzamin znikają z listy same, gdy minie ich data.": "You only tick off assignments. Tests and exams leave the list on their own once their date has passed.",
"Terminy dla całego roku wpisuje starosta, a zadania z Teams dochodzą same. Żółty znaczek „Data szacowana” oznacza, że prowadzący jeszcze nie podał daty: takie terminy są w osobnej sekcji.": "Deadlines for the whole year are entered by the class rep, and Teams assignments arrive on their own. The yellow “Estimated date” badge means the lecturer hasn't given a date yet: such dates are in a separate section.",
