"na motywy strony. Każdy motyw obejrzysz przed zakupem przyciskiem": "on site themes. You can try any theme before buying it with the",
"Podgląd": "Preview",
"Motyw możesz też dostać za darmo, gdy dojdziesz do jego poziomu. Monety zbierasz z pełnym dostępem.": "You can also get a theme for free when you reach its level. You earn coins with full access.",
"Odbierz nagrodę i kup motyw": "Claim a reward and buy a theme",
"Tydzień, semestr i grupa": "Week, semester and group",
"Zmień zakres, grupę albo przedmiot, a ranking przeliczy się od razu.": "Change the range, group or subject and the ranking updates right away.",
"Zrób zadanie, a potem kliknij Odbierz, żeby dostać monety.": "Do a task, then click Claim to get the coins.",
"Kupujesz za monety albo dostajesz za darmo po dojściu do poziomu.": "Buy them with coins or get them free when you reach the level.",
"Program studiów z semestrami 1–6 (z porównaniem przedmiotów do wyboru), lektury z katalogiem biblioteki, szkolenia obowiązkowe, motywy strony, język angielski i Twoje konto.": "Study programme with semesters 1–6 (with a comparison of electives), reading list with the library catalogue, mandatory training, site themes, English language and your account.",
"Na górze Więcej widzisz swój poziom, serię dni i odznaki z gier. Tu też w każdej chwili wrócisz do tego przewodnika.": "At the top of More you see your level, day streak and game badges. You can come back to this guide here at any time.",
"Słowniczek, gry, Hasło dnia, ranking, Twoje pliki i lektury.": "Glossary, games, Word of the day, ranking, your files and readings.",
"Sklep i monety, grupa, wygląd, konto i pomoc z tym przewodnikiem.": "Shop and coins, group, looks, account and help with this guide.",
"Przegrywasz we Fruń. Co się dzieje?": "You lose in Fly. What happens?",
"Gra się kończy i tracisz punkty": "The game ends and you lose points",
"Dostajesz pytanie z przedmiotu: dobra odpowiedź i grasz dalej": "You get a question from the subject: answer right and keep playing",
"Musisz czekać do jutra": "You have to wait until tomorrow",
"To Druga szansa: każda porażka to pytanie z materiałów.": "That’s the Second chance: every loss is a question from the materials.",
"Skąd biorą się monety 🪙?": "Where do coins 🪙 come from?",
"Z nauki: 10 punktów rankingu to 1 moneta, plus Zadania dnia": "From studying: 10 ranking points is 1 coin, plus Daily tasks",
"Kupuje się je za złotówki": "You buy them with złoty",
"Daje je prowadzący za obecność": "The lecturer gives them for attendance",
"Monety zarabiasz dobrymi odpowiedziami i Zadaniami dnia, a wydajesz na motywy.": "You earn coins with right answers and Daily tasks, and spend them on themes.",
"To część pełnego dostępu: {0} do końca 2. semestru albo {1}. Bez dostępu masz plan zajęć, własne wpisy w kalendarzu i darmowe próbki materiałów po zalogowaniu. Możesz też raz wypróbować wszystko za darmo przez 3 dni.": "It’s part of full access: {0} until the end of semester 2 or {1}. Without access you get the timetable, your own calendar entries and free material samples after signing in. You can also try everything free for 3 days, once.",
"Skąd biorę monety?": "Where do I get coins?",
"Za dobre odpowiedzi w quizach, Powtórkach, lekcjach i grach (10 punktów rankingu = 1 moneta) i za Zadania dnia. Wydajesz je w Więcej → Sklep i monety na motywy.": "For right answers in quizzes, Review, lessons and games (10 ranking points = 1 coin) and for Daily tasks. Spend them in More → Shop and coins on themes.",
"Czy inni widzą moje imię w rankingu?": "Can others see my name in the ranking?",
"Nie. W rankingu widać tylko pseudonim i punkty. Możesz się też całkiem ukryć w Więcej → Ranking: pseudonim i widoczność.": "No. The ranking shows only your nickname and points. You can also hide completely in More → Ranking: nickname and visibility.",
"Karta „Teraz zrób to” sama wybiera to, co w tej chwili najważniejsze. Klikasz jeden przycisk i działasz. Tu czeka też Hasło dnia, a przed kolokwium boss.": "The “Do this now” card picks what matters most right now. You click one button and go. The Word of the day waits here too, and before a test, the boss.",
"Słowniczek EN–PL, Twoje pliki, ranking kierunku, sklep z monetami, zasady zaliczeń z kalkulatorem średniej i konto.": "EN–PL glossary, your files, programme ranking, the coin shop, assessment rules with the grade average calculator, and your account.",
