"Napisz 2–3 zdania, jakbyś tłumaczył to koledze. Możesz po polsku.": "Write 2–3 sentences as if explaining it to a friend.",
"Porównaj z wzorem": "Compare with the model answer",
"Zaznacz, co masz w swojej odpowiedzi:": "Tick what your answer includes:",
"Wzorcowa odpowiedź": "Model answer",
"Bilet wyjścia": "Exit ticket",
"{0} pytania na zastosowanie. Co najmniej 2 dobre odpowiedzi i lekcja jest opanowana.": "{0} application questions. At least 2 correct answers and the lesson is mastered.",
"Lekcja opanowana ✓": "Lesson mastered ✓",
"Jeszcze nie opanowana": "Not mastered yet",
"Dobra robota. Jedno pytanie nie wyszło, więc rzuć okiem na tę część:": "Good job. One question didn't work out, so have a look at this part:",
"Rozumiesz ten temat. Fiszki i quiz pomogą go utrwalić.": "You understand this topic. Flashcards and the quiz will help it stick.",
"Nic straconego. Wróć do tych części, a fiszki z lekcji dodałem do powtórek:": "No harm done. Go back to these parts; the lesson's flashcards have been added to your reviews:",
"Część {0}: {1}": "Part {0}: {1}",
"Spróbuj biletu jeszcze raz": "Try the exit ticket again",
"✓ Oznaczona jako przerobiona (cofnij)": "✓ Marked as completed (undo)",
"Oznacz jako przerobioną bez biletu": "Mark as completed without the ticket",
"Nie tym razem. Poprawna odpowiedź to {0}.": "Not this time. The correct answer is {0}.",
"Fiszki z tej lekcji czekają w „Dziś do powtórki”.": "This lesson's flashcards are waiting in “Due today”.",
"Zaloguj się, żeby go otworzyć.": "Log in to open it.",
"Ten materiał możesz przejrzeć za darmo. Zaloguj się, żeby go otworzyć.": "You can view this material for free. Log in to open it.",
"Zaloguj się kodem z maila albo hasłem. Jeśli masz pełny dostęp, pojawi się po zalogowaniu.": "Log in with an e-mail code or your password. If you have full access, it will come back after you log in.",
"Wpisz e-mail, a my wyślemy 6-cyfrowy kod. Mail może wpaść do spamu. Kod jest ważny godzinę. Jeśli ustawiłeś hasło (Więcej → Konto i dostęp → Hasło do logowania), wybierz zakładkę „Hasło” i zaloguj się od razu.": "Enter your e-mail and we'll send a 6-digit code. The e-mail may land in spam. The code is valid for an hour. If you've set a password (More → Account & access → Login password), pick the “Password” tab and log in straight away.",
"kodem z maila albo hasłem": "with an e-mail code or a password",
". Przepisujesz go i już. Potem możesz ustawić hasło (Więcej → Konto i dostęp → Hasło do logowania) i logować się bez maila. Po zalogowaniu postęp (fiszki, quizy, oceny) zapisuje się na koncie i masz go na każdym urządzeniu.": ". You type it in and that's it. Later you can set a password (More → Account & access → Login password) and log in without the e-mail. Once you're logged in, your progress (flashcards, quizzes, grades) is saved to your account and you have it on every device.",
"Wpisz e-mail, a wyślemy Ci 6-cyfrowy kod. Jeśli masz już dostęp, użyj adresu, na który go kupiono.": "Enter your email and we'll send you a 6-digit code. If you already have access, use the address it was bought with.",
"Hasło": "Password",
"Sposób logowania": "Login method",
"Twoje hasło": "Your password",
"Wpisz hasło.": "Enter your password.",
"Nie pamiętam hasła: wyślij kod na maila": "Forgot my password: send a code by e-mail",
"Zły e-mail albo hasło. Nie ustawiłeś jeszcze hasła? Zaloguj się kodem z maila, a potem ustaw je w Więcej → Hasło do logowania.": "Wrong e-mail or password. Haven't set a password yet? Log in with an e-mail code, then set one in More → Login password.",
"Ten adres nie jest jeszcze potwierdzony. Zaloguj się raz kodem z maila.": "This address isn't confirmed yet. Log in once with an e-mail code.",
"Hasło do logowania": "Login password",
"ustawione · zmień": "set · change",
