"Zmień hasło": "Change password",
"Ustaw hasło": "Set password",
"Z hasłem zalogujesz się od razu, bez czekania na maila z kodem. Możesz to zrobić też później w Więcej → Hasło do logowania.": "With a password you log in instantly, without waiting for the code e-mail. You can also do it later in More → Login password.",
"Wpisz nowe hasło. Stare przestanie działać.": "Enter a new password. The old one will stop working.",
