"Następnym razem zaloguj się adresem {0} i hasłem. Kod z maila dalej działa, gdyby hasło wyleciało Ci z głowy.": "Next time, log in with {0} and your password. E-mail codes still work if you forget it.",
"Konto jest osobiste: działa na 3 urządzeniach i na jednym naraz, więc podanie hasła komuś i tak nic nie da.": "The account is personal: it works on 3 devices and on one at a time, so giving your password to someone won't help them anyway.",
