"Baza nie ma jeszcze listy urządzeń. Uruchom supabase/skrot-v8-urzadzenia.sql w Supabase → SQL Editor.": "The database doesn't have the device list yet. Run supabase/skrot-v8-urzadzenia.sql in Supabase → SQL Editor.",
"Lista urządzeń jeszcze się nie wczytuje, pracujemy nad tym. Konto działa normalnie.": "The device list isn't loading yet, we're working on it. Your account works normally.",
