"Właśnie uczysz się na: {0}. W jednej chwili konto działa na jednym urządzeniu.": "You're currently studying on: {0}. Your account works on one device at a time.",
"Właśnie uczysz się na: innym urządzeniu. W jednej chwili konto działa na jednym urządzeniu.": "You're currently studying on another device. Your account works on one device at a time.",
"Jeśli to Ty, kliknij „Używaj tutaj”, a tamto urządzenie się wstrzyma. Jeśli nie, ktoś zna Twoje konto: napisz do nas.": "If that's you, click “Use it here” and the other device will pause. If not, someone knows your account: write to us.",
"Masz już 3 urządzenia": "You already have 3 devices",
"Z konta korzystasz na maksymalnie {0} urządzeniach. Żeby dodać to urządzenie ({1}), usuń jedno z listy. Usuwać można raz na 30 dni.": "You can use your account on up to {0} devices. To add this device ({1}), remove one from the list. You can remove one every 30 days.",
"W trybie prywatnym albo po wyczyszczeniu danych przeglądarki strona widzi nowe urządzenie. Ucz się w zwykłym oknie.": "In a private window, or after clearing browser data, the site sees a new device. Study in a normal window.",
"Dostęp zablokowany": "Access blocked",
"Konto było używane przez kilka osób, co narusza regulamin (§ 3).": "The account was used by several people, which breaks the terms (§ 3).",
"Powód:": "Reason:",
"Jeśli to pomyłka, napisz na": "If this is a mistake, email",
". Odpowiemy w ciągu 14 dni.": ". We'll reply within 14 days.",
"Wczytuję…": "Loading…",
"Twoje urządzenia": "Your devices",
"Jedno konto = jedna osoba. Możesz mieć do {0} urządzeń (np. telefon i laptop), a w jednej chwili konto działa na jednym z nich.": "One account = one person. You can have up to {0} devices (e.g. a phone and a laptop), and the account works on one of them at a time.",
"Nie udało się wczytać urządzeń. Spróbuj za chwilę.": "Couldn't load your devices. Try again in a moment.",
"do 3 urządzeń · jedno konto = jedna osoba": "up to 3 devices · one account = one person",
"Ile urządzeń mogę mieć?": "How many devices can I use?",
"Do 3 (np. telefon, laptop, tablet), a w jednej chwili konto działa na jednym z nich. Gdy otworzysz stronę na drugim urządzeniu, kliknij „Używaj tutaj”. Urządzenie usuniesz w Więcej → Konto i dostęp → Twoje urządzenia, raz na 30 dni. Zgubiony telefon? Napisz do nas.": "Up to 3 (e.g. phone, laptop, tablet), and the account works on one of them at a time. When you open the site on another device, click “Use it here”. You can remove a device in More → Account & access → Your devices, once every 30 days. Lost your phone? Write to us.",
"Materiały z sylabusa": "Syllabus materials",
"Pojawią się tutaj, gdy prowadzący wrzuci prezentację do Teams. Do tego czasu ucz się z zakładki Z sylabusa.": "They'll appear here once the lecturer uploads a presentation to Teams. Until then, learn from the From the syllabus tab.",
