"Średnia ważona ECTS: każda ocena liczy się tyle razy, ile przedmiot ma punktów ECTS. Którą średnią bierze się pod uwagę przy stypendium, mówi regulamin świadczeń dla studentów US. Ocena 2,0 z którejkolwiek części oznacza, że tę część trzeba poprawić.": "ECTS-weighted average: each grade counts as many times as the subject has ECTS points. Which average counts for scholarships is set out in the US student benefits regulations. A 2.0 in any part means you have to resit that part.",
