"Pobierz plik z zakładki Pliki w kanale przedmiotu (PPTX, PDF lub DOCX) i upuść go poniżej. Prezentacja służy tylko jako mapa tematów: AI pisze opracowanie, fiszki i quiz od nowa, bez przepisywania slajdów. Przy każdym temacie zostaje odsyłacz do slajdów, a sam tekst slajdów nie jest nigdzie zapisywany.": "Download the file from the Files tab in the subject's channel (PPTX, PDF or DOCX) and drop it below. The presentation only serves as a topic map: the study notes, flashcards and quiz are written by AI, which doesn't see the slide text. Each topic keeps a reference to the slides, and the slide text itself isn't stored anywhere.",
