"Subskrypcja odnawia się sama, dopóki jej nie anulujesz. Po anulowaniu dostęp działa do końca opłaconego miesiąca.": "The subscription renews automatically until you cancel it. After cancelling, access works until the end of the paid month.",
"Nic się samo nie odnawia. Materiały się zablokują, a Twoje postępy i wpisy zostaną.": "Nothing renews automatically. Materials will be locked, but your progress and entries will stay.",
"Potwierdzenie płatności": "Payment confirmation",
"Mail ze Stripe. Faktury znajdziesz w „Zarządzaj subskrypcją”.": "Email from Stripe; invoices in “Manage subscription”.",
