"Konto bez pełnego dostępu. Masz darmowe próbki materiałów.": "Account without full access. You have free sample materials.",
"Zaloguj się e-mailem (bez hasła). Jeśli masz pełny dostęp, pojawi się po zalogowaniu.": "Log in with your e-mail (no password). If you have full access, it will come back after you log in.",
