"Pomoc": "Help",
"Usunięcie konta i danych: napisz z tego adresu na zdawalni.support@gmail.com.": "To delete your account and data, write from this address to zdawalni.support@gmail.com.",
"Płatność przeszła, ale nie mam dostępu": "I paid but don't have access",
"Zaloguj się adresem e-mail użytym przy płatności. Jeśli po kilku minutach dalej nie działa, napisz na zdawalni.support@gmail.com i dołącz potwierdzenie ze Stripe.": "Log in with the e-mail address you used for the payment. If it still doesn't work after a few minutes, write to zdawalni.support@gmail.com and attach the Stripe confirmation.",
"Gdzie jest potwierdzenie płatności albo faktura?": "Where is the payment confirmation or invoice?",
"Stripe wysyła je mailem zaraz po płatności. Przy subskrypcji miesięcznej wszystkie faktury są w „Zarządzaj subskrypcją” (Więcej → Konto i dostęp).": "Stripe e-mails them right after payment. With a monthly subscription, all invoices are in “Manage subscription” (More → Account & access).",
"Co się stanie, gdy skończy się dostęp?": "What happens when access ends?",
"Pełne materiały, quizy i terminy się zablokują, ale Twoje postępy i wpisy zostaną. Dostęp roczny nie odnawia się sam. Kalendarz w telefonie pokaże wtedy same zajęcia.": "Full materials, quizzes and deadlines will be locked, but your progress and entries stay. Yearly access doesn't renew automatically. Your phone calendar will then show only classes.",
"Logowanie nie działa": "Login doesn't work",
"Logujesz się bez hasła: wpisz e-mail, a my wyślemy 6-cyfrowy kod. Mail może wpaść do spamu. Kod jest ważny godzinę.": "You log in without a password: enter your e-mail and we'll send a 6-digit code. The e-mail may land in spam. The code is valid for an hour.",
"Zła grupa, złe zajęcia": "Wrong group, wrong classes",
"Więcej → Moja grupa. Zmiana działa od razu, także w kalendarzu w telefonie.": "More → My group. The change works instantly, including in your phone calendar.",
