"Wgrywanie własnych materiałów nie jest jeszcze włączone na serwerze. Daj znać staroście.": "Uploading your own materials isn't enabled on the server yet. Let the class rep know.",
"Limit: dziś zostało {0} z {1} plików, w tym miesiącu {2} z {3}. Każde przetworzenie (także ponowna próba) liczy się jako jeden plik.": "Limit: {0} of {1} files left today, {2} of {3} this month. Each processing run (including a retry) counts as one file.",
