"Funkcja AI na serwerze nie obsługuje jeszcze własnych materiałów. Daj znać staroście.": "The AI function on the server doesn't support your own materials yet. Let the class rep know.",
"Skończył się limit zapytań dla tego pliku. Wgraj go jeszcze raz.": "The request limit for this file has run out. Upload it again.",
"Prezentacja, notatki albo PDF. Zdawalni opracuje plik tak samo jak materiały roku: plik służy tylko jako mapa tematów, a skrót, wersję w prostym języku, pojęcia, fiszki i quiz AI pisze od nowa, z odsyłaczami do stron pliku. Sam tekst pliku nie jest nigdzie zapisywany. Wynik widzisz tylko Ty.": "A presentation, notes or a PDF. Zdawalni will process the file just like the year's materials: the file only serves as a topic map, and the summary, plain language, terms, flashcards and quiz are written from scratch, with references to the file's pages. The file's text itself isn't saved anywhere. Only you can see the result.",
