"W Analizie matematycznej każde wyjaśnienie (o co chodzi, temat, część lekcji, przykład z rozwiązaniem) da się kliknąć: student dostaje dużo prostszą wersję po polsku i łatwy przykład policzony krok po kroku. Tu je generujesz. Gotowe bloki są pomijane, więc możesz przerwać i wrócić; po zmianie opracowania uruchom jeszcze raz.": "In Mathematical Analysis every explanation (the gist, a topic, a lesson part, a worked example) can be clicked: the student gets a much simpler version in Polish and an easy example worked out step by step. Generate them here. Finished blocks are skipped, so you can stop and come back; run it again after the study notes change.",
