"Przerób materiały ze slajdów": "Rework materials from slides",
"Te materiały powstały bezpośrednio z prezentacji prowadzących. Przerobienie zrobi z nich opracowanie własne: AI bierze ze slajdów tylko listę tematów, pisze wyjaśnienia, przykłady, fiszki i quiz bez tekstu slajdów, a przy każdym temacie zostawia odsyłacz do slajdów. Potem zapisany tekst slajdów jest kasowany z bazy. Postęp studentów zostaje.": "These materials were created directly from the lecturers' presentations. Reworking will turn them into original study notes: the AI takes only the list of topics from the slides, writes explanations, examples, flashcards and a quiz without the slide text, and leaves a reference to the slides for each topic. Then the saved slide text is deleted from the database. Students' progress stays.",
