"ok. 1–2 minuty na materiał": "approx. 1–2 minutes per material",
"Prosty język i „Dlaczego?” przy quizach powstają z góry dla każdego materiału. Studenci tylko je czytają. Tu widzisz, czego brakuje, i uzupełniasz to jednym kliknięciem.": "Plain language and “Why?” for quizzes are created in advance for every material. Students only read them. Here you can see what's missing and fill it in with one click.",
