"Wymaga wdrożonej funkcji „claude” w Supabase z kluczem ANTHROPIC_API_KEY (instrukcja w README). Trwa ok. pół minuty na materiał; możesz zamknąć kartę i wrócić, gotowe zostaje zapisane.": "Requires the deployed “claude” function in Supabase with the ANTHROPIC_API_KEY key (instructions in the README). Takes about half a minute per material; you can close the tab and come back, finished work stays saved.",
