"Masz 20 zł i wolny wieczór. Możesz iść do kina albo kupić pizzę. Wybierasz kino. Twój koszt alternatywny to pizza, której nie zjesz.": "You have 20 zł and a free evening. You can go to the cinema or buy a pizza. You choose the cinema. Your cost is not just the ticket, but also the pizza you won't eat.",
