"📍 slajdy 12–15": "📍 slides 12–15",
"Każda decyzja ma ukryty koszt:": "Every decision has a hidden cost:",
", czyli wartość najlepszej opcji, z której rezygnujesz. Firma, która przeznacza pieniądze na reklamę, nie wyda ich na nową maszynę.": ", i.e. the value of the best option you give up. A company that spends money on advertising won't spend it on a new machine.",
