"tylko Twojej grupy": "only for your group",
"(C111, C112 albo C113) i Twojej podgrupy lab A lub B. Bez wybranej grupy widzisz wszystko naraz.": "(C111, C112 or C113) and your lab subgroup A or B. Without this you see everything at once.",
"Grupę zmienisz w każdej chwili w": "You can always change your group in",
"Więcej → Moja grupa": "More → My group",
"Kliknij swoją grupę": "Click your group",
"Ekran Dziś mówi, od czego zacząć": "The Today screen tells you where to start",
"Na górze ekranu Dziś jest karta": "At the top of the Today screen there's a card:",
"„Teraz zrób to”": "“Do this now”",
". Sama wybiera najważniejszą rzecz na teraz i daje jeden przycisk. Nie musisz niczego planować.": ". It picks the most important thing right now by itself and gives you one button. You don't need to plan anything.",
"Pod kartą: Twoje dzisiejsze zajęcia z salą, 3 najbliższe terminy i to, co doszło od ostatniej wizyty.": "Below the card: today's classes with rooms, the 3 nearest deadlines and what's new since your last visit.",
"Sprawdź 3 różne sytuacje": "Check 3 different situations",
"Zdawalni jak aplikacja": "Zdawalni as an app",
"Dodaj stronę do ekranu głównego telefonu. Otwiera się wtedy jednym stuknięciem, na pełnym ekranie, bez paska przeglądarki.": "Add the site to your phone's home screen. Then it opens with one tap, full screen, with no browser bar.",
"Nic nie kosztuje i nie zajmuje tyle miejsca co zwykła aplikacja.": "It costs nothing and doesn't take up space like a regular app.",
"Wybierz swój telefon": "Choose your phone",
"Logowanie bez hasła": "Login without a password",
"Wpisujesz e-mail, a my wysyłamy": "You enter your e-mail and we send you",
"6-cyfrowy kod": "a 6-digit code",
". Przepisujesz go i już. Po zalogowaniu postęp (fiszki, quizy, oceny) zapisuje się na koncie i masz go na każdym urządzeniu.": ". You type it in and that's it. Once you're logged in, your progress (flashcards, quizzes, grades) is saved to your account and you have it on every device.",
"Bez logowania postęp zostaje tylko w tej przeglądarce. Mail z kodem czasem wpada do spamu.": "Without logging in, your progress stays only in this browser. The email with the code sometimes lands in spam.",
"Zaloguj się w ćwiczeniu": "Log in (practice)",
"Tu codziennie zaczynasz. Jeden przycisk prowadzi do najważniejszej rzeczy na dziś.": "This is where you start every day. One button takes you to the most important thing for today.",
"Zajęcia Twojej grupy z godziną i salą. Kliknij przedmiot, żeby otworzyć jego materiały.": "Your group's classes with time and room. Click a subject to open its materials.",
"Grupa i konto": "Group and account",
"Tu zmienisz grupę, zalogujesz się i sprawdzisz, do kiedy masz dostęp.": "Here you change your group, log in and check how long your access lasts.",
