": quiz z całości, fiszki, zadania.": ": a quiz on everything, flashcards, tasks.",
": daty, zasady i przygotowanie do kolokwium. Zawsze w tej samej kolejności.": ": dates, rules and test prep. Always in the same order.",
"Na stronie przedmiotu u góry widzisz najbliższe zajęcia i temat, który pewnie na nich będzie.": "On a subject's cover you see the next class and the topic it will probably cover.",
"Zajrzyj do wszystkich 3 zakładek": "Look into all 3 tabs",
