"Odliczanie dni. Kliknij, żeby przeskoczyć do tego dnia.": "Day countdown. Click to jump to that day.",
"Strzałki zmieniają miesiąc, Dziś wraca do bieżącego dnia.": "Arrows change the month, Today goes back to the current day.",
"Skarby w zakładce Więcej": "Treasures in the More tab",
"Korzystasz ze słowniczka, własnych plików i kalkulatora średniej.": "You use the glossary, your own files and the grade average calculator.",
"Słowniczek angielski ↔ polski": "English ↔ Polish glossary",
"Wszystkie pojęcia ze wszystkich przedmiotów: termin po angielsku, tłumaczenie i jedno zdanie wyjaśnienia. Szukasz w obu językach.": "All terms from all subjects: the English term, its translation and a one-sentence explanation. You can search in both languages.",
"Idealny, gdy na wykładzie po angielsku pada słowo, którego nie znasz.": "Perfect when a word you don’t know comes up in an English lecture.",
"Znajdź pojęcie": "Find a term",
"Twoje własne pliki": "Your own files",
