"wgrywasz własną prezentację albo notatki. Opracujemy je tak samo jak materiały roku: opracowanie, fiszki, quiz i prosty język.": "you upload your own presentation or notes. We’ll process them just like the year’s materials: summary, flashcards, quiz and plain language, in your sections.",
"Widzisz je tylko Ty. Limit: 2 pliki dziennie i 40 w miesiącu.": "Only you can see them. Limit: 2 files per day and 40 per month.",
"Kalkulator średniej": "Grade average calculator",
"Zasadach zaliczeń": "Assessment rules",
"wpisujesz oceny, a strona liczy ocenę z przedmiotu według reguły z sylabusa i średnią semestru: zwykłą i ważoną ECTS.": "you enter your grades, and the site calculates the subject grade using the syllabus rule plus the semester average: simple and ECTS-weighted.",
