"To ta sama wiedza wytłumaczona jak dla 12-latka.": "It’s the same knowledge explained as if for a 12-year-old.",
"Co znaczy „📍 slajdy 12–15” przy temacie?": "What does “📍 slides 12–15” next to a topic mean?",
"Że temat zajmuje 4 strony": "That the topic takes up 4 pages",
"Że trzeba to wykuć na pamięć": "That you have to memorise it",
"To odsyłacz do prezentacji z Teams, gdy chcesz szczegółów z wykładu.": "It’s a reference to the Teams presentation, for when you want details from the lecture.",
"Fiszkę oceniasz „Łatwe”. Co się dzieje?": "You rate a flashcard “Easy”. What happens?",
