"To część pełnego dostępu: {0} do końca 2. semestru albo {1}. Bez dostępu masz plan zajęć, własne wpisy w kalendarzu i darmowe próbki materiałów po zalogowaniu.": "It’s part of full access: {0} until the end of semester 2 or {1}. Without access you get the timetable, your own calendar entries and free material samples after logging in.",
"Skąd są materiały?": "Where do the materials come from?",
"Prezentacje prowadzących z Teams służą tylko jako lista tematów. Opracowanie, przykłady, fiszki i quizy piszemy od nowa, a przy temacie zostaje odsyłacz do slajdów.": "The lecturers’ Teams presentations are only used as a list of topics. We write the study notes, examples, flashcards and quizzes from scratch, and a reference to the slides stays next to each topic.",
"Czy postęp się zapisuje?": "Is my progress saved?",
"Tak. Po zalogowaniu zapisuje się na koncie, więc masz go na każdym urządzeniu. Bez logowania tylko w tej przeglądarce.": "Yes. When logged in, on your account and on every device. Without logging in, only in this browser.",
"Nie widzę swoich zajęć albo terminów": "I can’t see my classes or deadlines",
"Sprawdź grupę w Więcej → Moja grupa. Terminy kolokwiów wymagają pełnego dostępu.": "Check your group in More → My group. Test dates require full access.",
"Znalazłem błąd w materiale": "I found a mistake in a material",
"Kliknij ⚑ Zgłoś błąd przy fiszce lub pytaniu albo napisz na zdawalni.support@gmail.com.": "Click ⚑ Report a mistake next to the flashcard or question, or write to zdawalni.support@gmail.com.",
