"Masz ustawioną grupę {0}. Zmienisz ją w Więcej → Moja grupa.": "Your group is set to {0}. You can change it in More → My group.",
"Masz ustawioną grupę {0}. Możesz ją zmienić tutaj albo później w Więcej → Moja grupa.": "Your group is set to {0}. You can change it here or later in More → My group.",
"Wybierz tutaj grupę i podgrupę lab, a w zajęciach i terminach zobaczysz tylko to, co Cię dotyczy. Przegląd leci dalej, nic nie musisz zamykać.": "Pick your group and lab subgroup right here, and your classes and deadlines will show only what concerns you. The tour carries on, nothing to close.",
"Wybierz grupę i podgrupę lab, a w zajęciach i terminach zobaczysz tylko to, co Cię dotyczy.": "Choose your group and lab subgroup, and classes and deadlines will show only what applies to you.",
"Dziś: od tego zaczynasz": "Today: start here",
"Karta „Teraz zrób to” sama wybiera to, co w tej chwili najważniejsze. Klikasz jeden przycisk i działasz.": "The “Do this now” card picks the most important thing right now. One button and you’re on it.",
"Wszystkie materiały: skrót, wersja w prostym języku, fiszki i quiz. Do tego wyszukiwarka": "All materials: summary, plain-language version, flashcards and quiz. Plus search",
"(klawisz /).": "(shortcut /).",
"Fiszki wracają same, zanim je zapomnisz. Pod spodem mapa tego, co już umiesz.": "Flashcards come back on their own before you forget them. Below, a map of what you already know.",
"Kolokwia, zadania, projekty i formalności, ułożone według pilności.": "Tests, assignments, projects and formalities, sorted by urgency.",
"Zajęcia, zaliczenia i Twoje własne wpisy. Możesz go też dodać do telefonu.": "Classes, exams and your own entries. You can also have it on your phone.",
"Słowniczek EN–PL, Twoje pliki, zasady zaliczeń z kalkulatorem średniej, konto.": "EN–PL glossary, your files, assessment rules with the grade average calculator, account.",
"To była wersja w minutę": "That was the one-minute version",
"Pełny przewodnik ma 9 krótkich rozdziałów z ćwiczeniami na przykładach i test na koniec. Zawsze znajdziesz go w Więcej.": "The full guide has 9 short chapters with exercises on examples and a test at the end. You’ll always find it in More.",
