"Pokażę Ci sześć zakładek. Każda odpowiada na jedno pytanie: co dziś, czego się uczyć, co powtórzyć, co na kiedy.": "I’ll show you six tabs. Each answers one question: what today, what to learn, what to review, what’s due when.",
