"W dniu zajęć podsumowanie pojawia się samo na ekranie Dziś, gdy zajęcia się skończą. Temat zajęć bierzemy od starosty albo z sylabusa (kolejne zajęcia = kolejne tematy).": "On the day of the class, the summary shows up on the Today screen by itself once the class is over. The topic comes from the class rep or from the syllabus (each class = the next topic).",
