"Staś tłumaczy temat, ale robi 2–3 błędy. Kliknij zdania, które są złe, i wybierz poprawkę.": "Stan explains a topic but makes 2–3 mistakes. Click the sentences that are wrong and pick the correction.",
"Kiedy poprawiasz kogoś innego, musisz naprawdę rozumieć temat, więc uczysz się głębiej niż przy samym czytaniu. Jedno wyjaśnienie to ok. 3 minuty.": "When you correct someone else, you have to really understand the topic, so you learn more deeply than by just reading. One explanation takes about 3 minutes.",
